arguments.argument:
menu_create(144, 100, 500, 260, 32, 0, 112, 16);
menumode = true;

if (room != Menu)
    menu_setdimmed();

menu_background(512, 24, 8, 12, 4);
bgtabs = true;

if (global.isHost or room == Menu)
{
    // Get all active RCON users
    if (room != Menu)
    {
        menu_divider("Active RCON Users");

        for (i=0; i<ds_list_size(global.rconUsers); i+=1)
        {
            player = ds_list_find_value(global.rconUsers, i);

            if (instance_exists(player))
            {
                menu_addedit_script(string(socket_remote_ip(player.socket)), player.name, '
                    var question;
                    question = show_question("Would you like to remove RCON access from this user?");
                    if (question)
                    {
                        rcon_user_remove(player);
                        rcon_remove_from_file(player, 0);
                        instance_destroy();
                        instance_create(x,y,ServerMgt_RCONUsers);
                    }

                    return item_name[virtualitem];
                ');
            }
        };
    }

    // Get all saved / inactive RCON users
    var rconUsersKey;
    rconUsersKey = ds_map_find_first(global.rconSavedUsers);
    if (room == Menu)
        menu_divider("RCON Users");
    else
        menu_divider("Inactive RCON Users");

    var rconUserFound;
    for (i=0; i<ds_map_size(global.rconSavedUsers); i+=1)
    {
        rconUserFound = false;
        if (room != Menu)
        {
            for (iUsers=0; i<ds_list_size(global.rconUsers); iUsers+=1)
            {
                var player, playerIP;
                player = ds_list_find_value(global.rconUsers, iUsers);
                if (instance_exists(player))
                {
                    if (object_is_ancestor(player.object_index, Player) or player.object_index == Player)
                    {
                        playerIP = string(socket_remote_ip(player.socket));

                        if (playerIP == rconUsersKey)
                        {
                            rconUserFound = true;
                            break;
                        }
                    }
                }
            };
        }

        if (!rconUserFound)
        {
            menu_addedit_script(rconUsersKey, ds_map_find_value(global.rconSavedUsers, rconUsersKey), '
                var question;
                question = show_question("Would you like to remove RCON access from this user?");
                if (question)
                {
                    rcon_remove_from_file(item_name[virtualitem], 1);
                    instance_destroy();
                    instance_create(x,y,ServerMgt_RCONUsers);
                }

                return item_name[virtualitem];
            ');
        }

        rconUsersKey = ds_map_find_next(global.rconSavedUsers, rconUsersKey);
    }
}

ServerMgt_menu_tabs();
